import{z as p,x as B,o as l,c as d,q as o,j as r,D as s,d as E,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"隔离与沙箱","description":"","frontmatter":{"title":"隔离与沙箱","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/isolation-sandbox.md","filePath":"cs/isolation-sandbox.md","lastUpdated":1791063341000}'),A={name:"cs/isolation-sandbox.md"};function m(c,a,C,h,f,u){const t=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=o('<h1 id="隔离与沙箱" tabindex="-1">隔离与沙箱 <a class="header-anchor" href="#隔离与沙箱" aria-label="Permalink to &quot;隔离与沙箱&quot;">​</a></h1><div class="epigraph"><p>把不可信代码放进权限更小的盒子：进程、虚拟机、seccomp 或语言运行时。盒子破了，损失应停在边界上。</p><footer>—— 据 Lampson 保护；Saltzer 完全中介；操作系统进程隔离的实践整理</footer></div><p><a href="/cs/cfi">上一课</a>在同一地址空间里加 NX 与随机化。本课不重讲页位。缺口是：越界与逻辑漏洞仍会发生，纵深要求<strong>缩小主体能碰的客体</strong>。<a href="/cs/kernel-user">内核与用户态</a>已把用户进程互相隔开；沙箱是更细的盒子：同一用户下再切，或把解析器、插件、渲染器丢掉大部分系统调用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程隔离依赖内核引用监视器与各自页表。同一进程里的库没有这层边界。缺口不是再讲页表漫游，而是多层隔离：进程、容器（命名空间+cgroup）、虚拟机、基于语言的 WASM/JVM、系统调用过滤。每一层对应威胁模型里「逃逸之后还剩什么」。</p><p><span class="marginnote">术语翻译：seccomp 就是「系统调用的白名单闸门」——给进程配一张允许调用的清单，越界调用直接被内核拒绝或杀进程；浏览器渲染器靠它把上千个系统调用砍到只剩几十个。</span></p><p><span class="marginnote">沙箱不是加密。它服务 CIA 的 C/I/A 中「损坏半径」：密钥与主机文件系统尽量不进盒子。侧信道表明：共享硬件时，逻辑盒子仍可能漏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>原则：不可信输入的处理者持最小能力集（对照<a href="/cs/capability-vs-acl">能力</a>）。浏览器多进程：渲染器无文件、无原始套接字。数据库 UDF、浏览器插件同构。本课不比较具体产品，只锁定：隔离 = 另一套页表或另一套系统调用策略 + 明确的数据通道。</p>',9)),(l(),r(n,null,{default:s(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNTRUST%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20BOX%5B%22%E6%9B%B4%E5%B0%8F%E6%9D%83%E9%99%90%E5%9F%9F%22%5D%0A%20%20BOX%20--%3E%20CH%5B%22%E6%98%BE%E5%BC%8F%E9%80%9A%E9%81%93%22%5D%0A%20%20BOX%20--%3E%20SC%5B%22%E5%90%8E%E8%AF%BE%3A%20%E4%BE%A7%E4%BF%A1%E9%81%93%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("隔离把保护矩阵的主体变细：不是「用户 www-data」，而是「渲染器实例 #12」。通道（管道、套接字、共享内存）必须再做认证与完整性，否则盒子外的信任会从通道流回去。这与"),e("a",{href:"/cs/two-pc"},"两阶段提交"),E("的参与者隔离不同：那里假设参与者诚实但会崩溃；这里假设盒子内代码不诚实。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：沙箱像医院的负压隔离病房——病人（不可信代码）在里面随便活动，但进出只走一条带认证的传递窗（显式通道）；传递窗忘了上锁，隔离就从窗口整体失效。")],-1)),a[6]||(a[6]=e("p",null,"三种盒子被穿透后各还剩哪层防线：",-1)),(l(),r(n,null,{default:s(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROC%5B%22%E8%BF%9B%E7%A8%8B%E7%9B%92%E5%AD%90%22%5D%20--%3E%7C%22%E9%80%83%E9%80%B8%E5%90%8E%22%7C%20USR%5B%22%E5%90%8C%E7%94%A8%E6%88%B7%E5%85%B6%E4%BB%96%E8%BF%9B%E7%A8%8B%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20CONT%5B%22%E5%AE%B9%E5%99%A8%E7%9B%92%E5%AD%90%22%5D%20--%3E%7C%22%E9%80%83%E9%80%B8%E5%90%8E%22%7C%20KERN%5B%22%E5%85%B1%E4%BA%AB%E5%86%85%E6%A0%B8%E5%8D%B3%20TCB%22%5D%0A%20%20VM%5B%22%E8%99%9A%E6%8B%9F%E6%9C%BA%E7%9B%92%E5%AD%90%22%5D%20--%3E%7C%22%E9%80%83%E9%80%B8%E5%90%8E%22%7C%20VMM%5B%22%E8%BF%98%E5%89%A9%E4%B8%80%E5%B1%82%E7%AE%A1%E7%90%86%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20KERN%20--%3E%20ALL%5B%22%E5%86%85%E6%A0%B8%E6%BC%8F%E6%B4%9E%E5%8F%AF%E4%B8%80%E6%AC%A1%E6%89%93%E7%A9%BF%E6%89%80%E6%9C%89%E5%AE%B9%E5%99%A8%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>TCB 含内核与监视器。盒子再小，内核漏洞仍是公共逃逸面。缩小 TCB 是微内核对照，不插入本课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>逻辑隔离不关共享缓存、时间、风扇噪声——下一课侧信道。也不要把容器当成虚拟机级的威胁模型。内核漏洞可以一次打穿所有进程盒子；那是 TCB 大小问题，不是「没开 ASLR」。</p><p><span class="marginnote">常见误区：初学者容易把容器当「轻量虚拟机」。容器只是被命名空间切开的普通进程，与宿主共享同一内核；虚拟机才多出一层管理程序，逃逸面因此更窄。</span></p><p>沙箱逃逸是「盒子的引用监视器被绕过」，与盒内越界是不同边界。后课默认：逻辑边界已尽量缩小；共享微结构仍可能泄漏密钥比特。</p><p>盒子的数据通道上仍要认证与完整性，否则隔离只是把敌手挪到管道对端。通道策略与盒子权限同样是矩阵的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>后课默认：逻辑盒子已尽量小，微结构泄漏另计。</p></li><li><p>容器与虚拟机的威胁模型不同：前者共享内核，后者多一层管理程序。</p></li><li><p>后课侧信道说明共享硬件时逻辑盒子仍可能漏密钥。</p></li><li><p>NX/ASLR 在盒内减可利用性；本课用更小权限域限制爆炸半径。</p></li><li><p>通道必须显式；沙箱不是加密。</p></li><li><p>共享硬件上的泄漏是侧信道课的缺口。</p></li><li><p>出处：Lampson；Saltzer and Schroeder；操作系统隔离实践。</p></li></ul>',8))])}const _=p(A,[["render",m]]);export{T as __pageData,_ as default};
